import java.util.*;

public class Main {
    static String solve, s;
    static int N;

    static void Check(){
        if(solve.charAt(0) == '.'){
            solve = solve.substring(1);
            solve = "dot" + solve;
        }
        else if(solve.charAt(0) == '@'){
            solve = solve.substring(1);
            solve = "at" + solve;
        }

        if(solve.charAt(solve.length() - 1) == '.'){
            solve = solve.substring(0, solve.length() - 1);
            solve += "dot";
        }
        else if(solve.charAt(solve.length() - 1) == '@'){
            solve = solve.substring(0, solve.length() - 1);
            solve += "at";
        }
    }

    public static void main(String[] args){
        Scanner scanner = new Scanner(System.in);
        s = scanner.next();

        N = s.length();

        solve = "";

        for(int I = 0; I < N; ++I){

            if(I + 3 <= N){
                if(s.substring(I, I + 3).equals("dot")){
                    solve += ".";
                    I += 2;
                }
                else{
                    if(I + 2 <= N){
                        if(s.substring(I, I + 2).equals("at")){
                            solve += "@";
                            I += 1;
                        }
                        else solve += s.charAt(I);
                    }
                    else solve += s.charAt(I);
                }
            }
            else if(I + 2 <= N){
                if(s.substring(I, I + 2).equals("at")){
                    solve += "@";
                    I += 1;
                }
                else solve += s.charAt(I);
            }
            else solve += s.charAt(I);
        }

        Check();

        int cont = 0;

        for(int I = 0; I < solve.length(); ++I){
            if(solve.charAt(I) == '@') ++cont;
        }

        StringBuilder output = new StringBuilder();

        if(cont == 1){
            output.append(solve);
        }
        else{
            boolean ok = true;

            for(int I = 0; I < solve.length(); ++I){

                if(solve.charAt(I) == '@'){
                    if(ok){
                        output.append('@');
                        ok = false;
                    }
                    else{
                        output.append("at");
                    }
                    continue;
                }
                output.append(solve.charAt(I));
            }
        }

        System.out.println(output.toString());
    }
}
